    "content": "import time
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if ttl is not None and ttl <= 0:
            raise ValueError('ttl must be a positive number')
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.expirations = 0

    def put(self, key, value, ttl=None):
        if ttl is not None:
            ttl = ttl
        else:
            ttl = self.ttl
        if ttl is not None:
            expiration = self.clock() + ttl
        else:
            expiration = None
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = (value, expiration)
        if len(self.cache) > self.capacity:
            self.purge_expired()

    def get(self, key, default=None):
        if key in self.cache:
            value, expiration = self.cache[key]
            if expiration is not None and expiration < self.clock():
                self.cache.pop(key)
                self.expirations += 1
                return default
            self.cache.move_to_end(key)
            return value
        return default

    def __contains__(self, key):
        return key in self.cache

    def __len__(self):
        return len(self.cache)

    def keys(self):
        return self.cache.keys()

    def purge_expired(self):
        expired_count = 0
        while self.cache and self.cache[self.cache.keys()[0]][1] is not None and self.cache[self.cache.keys()[0]][1] < self.clock():
            self.cache.popitem(last=False)
            expired_count += 1
        return expired_count

    def stats(self):
        return {'expirations': self.expirations}


def memoize(maxsize, ttl=None, clock=time.monotonic):
    def decorator(func):
        cache = LRUCache(capacity=maxsize, ttl=ttl, clock=clock)
        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items()))
            if key in cache:
                value, expiration = cache.get(key)
                if expiration is not None and expiration < clock():
                    cache.purge_expired()
                    return func(*args, **kwargs)
                return value
            value = func(*args, **kwargs)
            cache.put(key, value)
            return value
        return wrapper
    return decorator"
  },
  "thought": "Implemented the LRUCache class with TTL support and a memoize decorator.",
  "tool": "write"
}

